<script>
(()=>{const root=document.getElementById('create');if(!root||root.dataset.sfReady)return;root.dataset.sfReady='true';const cards=[...root.querySelectorAll('[data-sf-card]')],filters=[...root.querySelectorAll('[data-sf-filter]')],search=root.querySelector('[data-sf-search]'),preview=root.querySelector('#sf-preview'),list=root.querySelector('.sf-list'),layout=root.querySelector('.sf-layout'),reduce=matchMedia('(prefers-reduced-motion: reduce)'),mobile=matchMedia('(max-width: 760px)');let selected=cards[0],group='all',paused=reduce.matches,visible=true;
function place(){if(mobile.matches&&selected&&!selected.hidden){const shown=cards.filter(c=>!c.hidden),index=shown.indexOf(selected);shown[Math.min(shown.length-1,index%2?index:index+1)].after(preview)}else layout.append(preview)}
function motion(){root.classList.toggle('sf-paused',paused||reduce.matches||!visible||document.hidden);root.querySelector('[data-sf-motion]').setAttribute('aria-label',paused?'Play preview animation':'Pause preview animation');root.querySelector('[data-sf-motion]').innerHTML='<i class="fas '+(paused?'fa-play':'fa-pause')+'" aria-hidden="true"></i>'}
function choose(card){selected=card;cards.forEach(c=>{c.classList.toggle('sf-selected',c===card);c.setAttribute('aria-pressed',String(c===card))});const d=card.dataset;preview.dataset.art=d.art;preview.style.setProperty('--sf-accent',d.color);root.querySelector('[data-sf-title]').textContent=d.name;root.querySelector('[data-sf-description]').textContent=d.desc;root.querySelector('[data-sf-usage]').textContent=d.usage;root.querySelector('[data-sf-use]').hidden=!d.usage;const create=root.querySelector('[data-sf-create]');if(create)create.href=d.create;const demo=root.querySelector('[data-sf-demo]');demo.hidden=!d.demo;if(d.demo)demo.href=d.demo;else demo.removeAttribute('href');root.querySelector('[data-sf-scene]').replaceChildren(root.querySelector('[data-sf-template="'+d.sfCard+'"]').content.cloneNode(true));place();motion()}
function apply(){const q=search.value.trim().toLocaleLowerCase(),matches=c=>(c.dataset.name+' '+c.dataset.desc).toLocaleLowerCase().includes(q);let shown=0;cards.forEach(c=>{c.hidden=!(matches(c)&&(group==='all'||c.dataset.group===group));if(!c.hidden)shown++});filters.forEach(f=>{f.setAttribute('aria-pressed',String(f.dataset.sfFilter===group));f.querySelector('span').textContent=cards.filter(c=>matches(c)&&(f.dataset.sfFilter==='all'||c.dataset.group===f.dataset.sfFilter)).length});root.querySelector('[data-sf-results]').textContent='Showing '+shown+' of '+cards.length+' formats';root.querySelector('[data-sf-empty]').hidden=shown!==0;preview.hidden=shown===0;if(shown&&(selected.hidden||!selected))choose(cards.find(c=>!c.hidden));else place()}
cards.forEach(c=>c.addEventListener('click',()=>choose(c)));filters.forEach(f=>f.addEventListener('click',()=>{group=f.dataset.sfFilter;apply()}));search.addEventListener('input',apply);root.querySelector('[data-sf-reset]').addEventListener('click',()=>{search.value='';group='all';apply();search.focus()});root.querySelector('[data-sf-motion]').addEventListener('click',()=>{paused=!paused;motion()});root.querySelector('[data-sf-register]')?.addEventListener('click',event=>{if(window.Alpine){event.preventDefault();window.dispatchEvent(new CustomEvent('open-auth',{detail:{tab:'register'}}))}if(window.trackMarketingEvent)window.trackMarketingEvent('landing_home_cta','format_create')});mobile.addEventListener('change',place);reduce.addEventListener('change',()=>{paused=reduce.matches;motion()});document.addEventListener('visibilitychange',motion);if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;motion()},{threshold:.05}).observe(root);place();motion();})();
</script>
